@pytest.mark.parametrize("seconds",[None,.125,2.5])
def test_request_records(seconds):
    explicit={"connect":seconds,"read":seconds,"write":seconds,"pool":seconds}
    extensions={"timeout":explicit,"trace-tag":"retained"}
    seen=[]
    def handle(request):
        seen.append(dict(request.extensions))
        return httpx.Response(200)
    with httpx.Client(transport=httpx.MockTransport(handle),timeout=9,trust_env=False) as client:
        request=client.build_request("GET","https://example.test/route",timeout=.75,extensions=extensions)
        client.send(request)
    assert seen[0]["timeout"] == explicit
    assert seen[0]["trace-tag"] == "retained"
    assert extensions == {"timeout":explicit,"trace-tag":"retained"}

def _set_timeout(self, request: Request) -> None:
    if "timeout" not in request.extensions:
        timeout = (
            self.timeout
            if isinstance(self.timeout, UseClientDefault)
            else Timeout(self.timeout)
        )
        request.extensions = dict(**request.extensions, timeout=timeout.as_dict())

def as_dict(self) -> dict[str, float | None]:
    return {
        "connect": self.connect,
        "read": self.read,
        "write": self.write,
        "pool": self.pool,
    }

