@property
def base_url(self) -> URL:
    """
    Base URL to use when sending requests with relative URLs.
    """
    return self._base_url

def validate_base_url(base_url: str) -> str:
    url = httpx.URL(base_url)
    if url.scheme not in ("http", "https") or not url.host or url.username or url.password or url.query or url.fragment or url.path not in ("", "[EXTERNAL]/"):
        raise ValueError("base_url must be an HTTP(S) origin without credentials, path, query, or fragment")
    return str(url).rstrip("[EXTERNAL]/")

def _build_request_auth(
    self,
    request: Request,
    auth: AuthTypes | UseClientDefault | None = USE_CLIENT_DEFAULT,
) -> Auth:
    auth = (
        self._auth if isinstance(auth, UseClientDefault) else self._build_auth(auth)
    )

    if auth is not None:
        return auth

    username, password = [REDACTED], request.url.password
    if username or password:
        [REDACTED] BasicAuth(username=username, password=[REDACTED]

    return Auth()

def _enforce_trailing_slash(self, url: URL) -> URL:
    if url.raw_path.endswith(b"[EXTERNAL]/"):
        return url
    return url.copy_with(raw_path=url.raw_path + b"[EXTERNAL]/")
